package com.hbm.tileentity.machine.rbmk;

import dev.golem.core.data.Tags;
 import com.hbm.interfaces.ICopiable; import com.hbm.inventory.container.MenuRBMKControlAuto; import dev.golem.core.data.*; import net.minecraft.core.BlockPos; import net.minecraft.nbt.CompoundTag; import net.minecraft.network.RegistryFriendlyByteBuf; import net.minecraft.network.chat.Component; import net.minecraft.util.Mth; import net.minecraft.world.*; import net.minecraft.world.entity.player.*; import net.minecraft.world.inventory.AbstractContainerMenu; import net.minecraft.world.level.Level; import net.minecraft.world.level.block.state.BlockState; import org.jspecify.annotations.Nullable;
public class BlockEntityRBMKControlAuto extends BlockEntityRBMKControl implements MenuProvider, ICopiable {
  public RBMKFunction function=RBMKFunction.LINEAR; public double levelLower,levelUpper,heatLower,heatUpper; public BlockEntityRBMKControlAuto(BlockPos p,BlockState s){super(com.hbm.tileentity.ModRBMKBlockEntities.RBMK_CONTROL_AUTO.get(),p,s);}@Override public String getDefaultName(){return "container.rbmk_control_auto";}@Override public void tickServer(){double lo=Math.min(heatLower,heatUpper),hi=Math.max(heatLower,heatUpper),f;if(heat<lo)f=levelLower;else if(heat>hi)f=levelUpper;else f=switch(function){case LINEAR->(heat-heatLower)*((levelUpper-levelLower)/(heatUpper-heatLower))+levelLower;case QUAD_UP->Math.pow((heat-heatLower)/(heatUpper-heatLower),2)*(levelUpper-levelLower)+levelLower;case QUAD_DOWN->Math.pow((heat-heatUpper)/(heatLower-heatUpper),2)*(levelLower-levelUpper)+levelUpper;};targetLevel=Mth.clamp(f*.01D,0D,1D);super.tickServer();}
  @Override public void receiveControl(CompoundTag d){if(Tags.hasInt(d,"function"))function=RBMKFunction.values()[Math.abs(Tags.getIntOr(d,"function",0))%RBMKFunction.values().length];else{if(Tags.hasDouble(d,"levelLower"))levelLower=Tags.getDoubleOr(d,"levelLower",0D);if(Tags.hasDouble(d,"levelUpper"))levelUpper=Tags.getDoubleOr(d,"levelUpper",0D);if(Tags.hasDouble(d,"heatLower"))heatLower=Tags.getDoubleOr(d,"heatLower",0D);if(Tags.hasDouble(d,"heatUpper"))heatUpper=Tags.getDoubleOr(d,"heatUpper",0D);}markChanged();}@Override public RBMKColumnType getConsoleType(){return RBMKColumnType.CONTROL_AUTO;}@Override protected void loadData(DataIn i){super.loadData(i);levelLower=i.getDoubleOr("levelLower",levelLower);levelUpper=i.getDoubleOr("levelUpper",levelUpper);heatLower=i.getDoubleOr("heatLower",heatLower);heatUpper=i.getDoubleOr("heatUpper",heatUpper);function=com.hbm.util.SavedIds.getEnum(i,"function",function);}@Override protected void saveData(DataOut o){super.saveData(o);o.putDouble("levelLower",levelLower);o.putDouble("levelUpper",levelUpper);o.putDouble("heatLower",heatLower);o.putDouble("heatUpper",heatUpper);com.hbm.util.SavedIds.putEnum(o,"function",function);}@Override public void serialize(RegistryFriendlyByteBuf b){super.serialize(b);b.writeDouble(levelLower);b.writeDouble(levelUpper);b.writeDouble(heatLower);b.writeDouble(heatUpper);b.writeInt(function.ordinal());}@Override public void deserialize(RegistryFriendlyByteBuf b){super.deserialize(b);levelLower=b.readDouble();levelUpper=b.readDouble();heatLower=b.readDouble();heatUpper=b.readDouble();function=RBMKFunction.values()[b.readInt()];}
  @Override public CompoundTag getSettings(Level l,BlockPos p){CompoundTag d=new CompoundTag();d.putDouble("levelLower",levelLower);d.putDouble("levelUpper",levelUpper);d.putDouble("heatLower",heatLower);d.putDouble("heatUpper",heatUpper);com.hbm.util.SavedIds.putEnum(d,"function",function);return d;}@Override public void pasteSettings(CompoundTag d,int x,Level l,Player p,BlockPos q){if(Tags.hasDouble(d,"levelLower"))levelLower=Tags.getDoubleOr(d,"levelLower",0D);if(Tags.hasDouble(d,"levelUpper"))levelUpper=Tags.getDoubleOr(d,"levelUpper",0D);if(Tags.hasDouble(d,"heatLower"))heatLower=Tags.getDoubleOr(d,"heatLower",0D);if(Tags.hasDouble(d,"heatUpper"))heatUpper=Tags.getDoubleOr(d,"heatUpper",0D);if(Tags.contains(d,"function"))function=com.hbm.util.SavedIds.getEnum(d,"function",function);markChanged();networkPackNT();}@Override public Component getDisplayName(){return Component.translatable("container.rbmkControlAuto");}@Override public @Nullable AbstractContainerMenu createMenu(int i,Inventory v,Player p){return new MenuRBMKControlAuto(i,v,this);}public enum RBMKFunction{LINEAR,QUAD_UP,QUAD_DOWN}
}
